const fs = require('fs');
const vm = require('vm');
const html = fs.readFileSync('/tmp/acc/previews/index.html', 'utf8');
const script = html.match(/<script>([\s\S]*?)<\/script>/)[1];

function makeDoc() {
  const box = { value: '', _listener: null,
    addEventListener(ev, fn) { this._listener = fn; } };
  const emptyRow = { hidden: true };
  const countBox = { textContent: '' };
  const rows = [ {hidden:false}, {hidden:false}, {hidden:false} ];
  const document = {
    getElementById(id) {
      if (id === 'contact-search') return box;
      if (id === 'search-empty-row') return emptyRow;
      if (id === 'visible-count') return countBox;
      return null;
    },
    getElementsByClassName(cls) {
      return cls === 'retained-row' ? rows : [];
    },
  };
  return { box, emptyRow, countBox, rows, document };
}

const d = makeDoc();
vm.runInNewContext(script, { document: d.document });
// initial applyFilter() ran at load
const results = [];
function snap(q) {
  results.push({
    query: q,
    count: d.countBox.textContent,
    hintHidden: d.emptyRow.hidden,
    visibles: d.rows.map(r => !r.hidden),
  });
}
snap('(initial)');
for (const q of ['shared', 'zzz', '', 'Shared', 'b@', '']) {
  d.box.value = q;
  d.box._listener(new Event('input'));
  snap(q);
}
for (const r of results) console.log(JSON.stringify(r));
EOF
